	public function beforeSave()
    {
		//quando um controle está bloqueado ele não é enviado no POST, devemos setar como falso.
        if ($this->presenca != true )
			  $this->presenca = false;

        //se for um coordenador/admin que está fazendo uma inscrição manual, e esta foi feita após o fim da atividade.
        //Presupoe-se que o participante estava presente, portanto a presença é dada para agilizar o processo.
        $normaluser=false;
        $roles=Rights::getAssignedRoles(Yii::app()->user->Id); // check for single role
        foreach($roles as $role)
            if($role->name == 'Authenticated')
            {
                $normaluser=true;
            }
        $model1=Atividade::model()->findbyPK($this->id_atividade);
        date_default_timezone_set('America/Sao_Paulo');
        $date1 = new DateTime("now");
        $model1->data= str_replace('/', '-', $model1->data);
        $date2= new DateTime($model1->data.' '.$model1->horafinal);
        if ( $date1 > $date2 && !$normaluser && Yii::app()->controller->action->id=='create')
        {
            $this->presenca=true;
        }
        return parent::beforeSave();
    }

    //Verifica se o usuário irá remover uma atividade que já ocorreu. Um Admin ou coordenador pode.
    public function beforeDelete()
    {
        $normaluser=false;
        $roles=Rights::getAssignedRoles(Yii::app()->user->Id); // check for single role
        foreach($roles as $role)
            if($role->name == 'Authenticated')
            {
                $normaluser=true;
            }
        $model1=Atividade::model()->findbyPK($this->id_atividade);
        date_default_timezone_set('America/Sao_Paulo');
        $date1 = new DateTime("now");
        $model1->data= str_replace('/', '-', $model1->data);
        $date2= new DateTime($model1->data.' '.$model1->horafinal);
        if ( $date2 < $date1 && $normaluser )
        {
            $this->addError('id_atividade','Atividade "'.$model1->tema.'" não pode ser removida pois a atividade já ocorreu');
            return false;
        }
        return parent::beforeDelete();
    }

