    public function checkChoque($atribbute)
    {
        if ($this->hasErrors())
            return;
        $model1=Atividade::model()->findbyPK($this->id_atividade);
        //se for uma atividade nao eletiva, não precisa checar o horário.
        if ($model1->eletivo == false ) 
            return; 
        //Se for update de presença tambémm nao, teoricamente tudo já foi checado
        if((Yii::app()->controller->action->id=='delete' || Yii::app()->controller->action->id=='update' )&& Yii::app()->controller->id=='inscricaoatividade')
            return;

        //check se as vagas estão ainda disponíveis desde a última visualização do usuário
        $normaluser=false;
        $roles=Rights::getAssignedRoles(Yii::app()->user->Id); // check for single role
        foreach($roles as $role)
            if($role->name == 'Authenticated')
            {
                $normaluser=true;
            }
        if ($model1->vagasdisponiveis < 1 and $normaluser==true)
        {
          $this->addError($atribbute,'Atividade "'.$model1->tema.'" teve suas vagas esgotadas neste momento, seja mais rápido da próxima vez');
          return;
        }

        //Agora e se estiver entre os três primeiros dias ?
        /*if ($model1->subevento != 'III Semana do Livro e da Biblioteca' && 
        $model1->subevento != 'III SECITEC- Semana de Ciência e Tecnologia')
        {
            $criteria2 = new CDbCriteria;
            $criteria2->select = 't.*,tu.*';
            $criteria2->join = 'LEFT JOIN atividade AS tu ON t.id_atividade = tu.id';
            $criteria2->addCondition("id_inscricao=:param1 AND 
            subevento NOT IN ('III SECITEC- Semana de Ciência e Tecnologia','III Semana do Livro e da Biblioteca',
            :param2) ");
            $criteria2->params =array(':param1'=>(int)$this->id_inscricao,':param2'=>$model1->subevento );
            
            $results=Inscricaoatividade::model()->findAll($criteria2);
                                    
            if ($results!= null)
            {
                $this->addError($atribbute,'Escolha ativdades da III Semana do Livro, III SECITEC ,acrescido de UMA semana dos cursos.Esta restrição será removida no dia 07 de outubro.');
                return;
            }
        }*/
        
        //Choque de horários  apenas com eletivos.
        $criteria = new CDbCriteria;
        $criteria->select = 't.*,tu.*';
        $criteria->join = 'LEFT JOIN atividade AS tu ON t.id_atividade = tu.id';
        $criteria->addCondition("eletivo=true AND data=:param1 AND id_inscricao=:param4 AND tu.id !=:param0 AND(
        (:param2 >= horainicial AND :param3 <= horafinal) OR
        (:param2 <= horainicial AND :param3 >= horafinal) OR
        (:param2 < horafinal AND :param3 >= horafinal) OR 
        (:param2 <= horainicial AND :param3 > horainicial)
        ) ");
        
        $criteria->params =array(':param4'=>$this->id_inscricao,':param0'=>$this->id_atividade,
        ':param1' =>$model1->data, ':param2' => $model1->horainicial , ':param3'=>$model1->horafinal);
        $modelsx=Inscricaoatividade::model()->findAll($criteria);

        if ($modelsx != null)
        {
            $atividadex = Atividade::model()->findbyPK($modelsx[0]->id_atividade); 
            $this->addError($atribbute,'Atividade "'.$model1->tema.'" não pode ser inserida pois o horário é conflitante com a atividade "'.$atividadex->tema.'"   ');
            return ;
        }
        
        //se ele escolher uma atividade que pode apenas uma . Atividades exclusivas
        if ($this->id_atividade == 275 ||
            $this->id_atividade == 276 ||
            $this->id_atividade == 277 ||
            $this->id_atividade == 278 ||
            $this->id_atividade == 279
        )
        {
            $atividadesex = Inscricaoatividade::model()->findAllAttributes(null,true,"id_inscricao=:param1 AND id_atividade in (275,276,277,278,279)",array('param1'=>$this->id_inscricao));
            if (count($atividadesex) > 0) 
            {
               $this->addError($atribbute,'A atividade "'.$model1->tema.'" não pode ser escolhida');
               return;  
            }
        }
        
        //agora veja se o participante deseja inserir  um evento que já ocorreu . Hack ou inscrições no último minuto
        $normaluser=false;
        $roles=Rights::getAssignedRoles(Yii::app()->user->Id); // check for single role
        foreach($roles as $role)
            if($role->name == 'Authenticated')
            {
                $normaluser=true;
            }
        date_default_timezone_set('America/Sao_Paulo');
        $date1 = new DateTime("now");
        $model1->data= str_replace('/', '-', $model1->data);
        $date2= new DateTime($model1->data.' '.$model1->horafinal);
        $date2->add(new DateInterval("PT2H"));
        if ( $date2 < $date1 && $normaluser)
        {
            $this->addError($atribbute,'Atividade "'.$model1->tema.'" já ocorreu e não pode ser inserida.') ;
        }
    }
    
