	public function search() {

        $criteria = new CDbCriteria;

		if ($this->id > 0 ) {

            $criteria->compare('id_evento', $this->id);
            if ( $this->presenca=='0' || $this->presenca=='1' ) {
                $criteria->compare('presenca', $this->presenca);
            }
            if ($this->id_atividade > 0)
                $criteria->compare('id_atividade', $this->id_atividade);

            $criteria->join = 'LEFT JOIN "Inscricao" ON t.id_inscricao="Inscricao".id 
            LEFT JOIN "DadosPessoais" on "Inscricao".cpf_dadospessoais="DadosPessoais".cpf';
            $criteria->order = 'unaccent_string("DadosPessoais".nome)';

            if ($this->id_inscricao) {
                $criteria->addCondition('unaccent_string("DadosPessoais".nome) ' . "ilike unaccent_string('%'||:param1||'%')");
                $criteria->params= array_merge($criteria->params,[':param1' => $this->id_inscricao]);
            }
        }else {
            $criteria->compare('id', 0);
        }


		return new CActiveDataProvider($this, array(
			'criteria' => $criteria,
            'Pagination' => array (
                'PageSize' => 30
              ),
		));
	}
